// script/site-truth/lib.ts — the ONE derivation of "what the engine actually declares".
//
// WHY THIS MODULE EXISTS
// ---------------------
// The website's language dataset used to be hand-maintained while its header
// claimed it was generated by `.tools/rebuild-languages.ts` — a script that does
// not exist in this repository. The dataset went stale in exactly the ways a
// hand-maintained copy goes stale: the engine grew two registry languages
// (matlab, vba) with no display family, the emitted relationship vocabulary grew
// from ten to fourteen with the site still claiming ten, and one family claimed a
// registry id (`sass`) whose files the engine routes to a DIFFERENT analyzer.
//
// So the dataset is generated again, and every derived field is read from the
// same source of truth the product reads:
//
//   registry languages + deduped grammar map   <- src/ast/engine.ts SUPPORTED_LANGUAGES
//   language -> analyzer module                <- src/ast/engine.ts getAnalyzer() switch
//   extension -> language routing (+ sniffing) <- src/ast/language-detection.ts
//   emitted relationship vocabulary            <- src/ast/types.ts RelationshipType enum
//   what one analyzer can construct            <- src/ast/real-<module>-analyzer.ts
//
// WHAT IS *NOT* DERIVED, AND WHY THAT IS SAID OUT LOUD
// ----------------------------------------------------
// Display name, icon, brand colour, the authored `extracts` line and the
// ecosystem band are editorial: no source file records them. They live in
// generate-languages.ts's FAMILY_INPUT table, which the generator validates
// against the derived inventory (a missing or extra row fails the run). The
// derived fields can never be typed in; the editorial fields can never be
// silently dropped.
//
// A note carried over from verify-languages-surface.ts, still true: emission
// capability is derived by a broad source scan (RelationshipType.X members,
// literal `type:`/`relationshipType:`/`label:` values filtered to the enum, the
// positional `rel(scope, "x", …)` helper, and delegation to sub-analyzers). It
// is deliberately an OVER-report: the dangerous direction for this gate is a
// family claiming LESS than its analyzer can construct, which is exactly how the
// deleted `tier` defamed four languages. What over-reports here is the claim the
// site publishes; m60's rel-type-coverage gate is the independent audit of the
// same source, and a type that scan cannot see would fail there first.

import { existsSync, readFileSync, readdirSync } from "node:fs"
import path from "node:path"

export const ROOT = path.resolve(import.meta.dirname ?? ".", "../..")

export function readRepo(rel: string): string {
  return readFileSync(path.join(ROOT, rel), "utf8")
}

export function repoPath(rel: string): string {
  return path.join(ROOT, rel)
}

// ── 1. The registry: src/ast/engine.ts SUPPORTED_LANGUAGES ────────────────────
//
// A JS object literal keeps the LAST value for a repeated key, so the resolved
// map does the same — and the declaration list is kept so a shadowed duplicate
// can be detected rather than silently counted. `nim` was declared twice
// (`tree-sitter-nim`, then `__generic__`) and the shadowed key certified that nim
// had no parser while the wasm switch, the vendored grammar and a pinned fixture
// set all said otherwise. That duplicate is gone; the detection stays.
//
// METHOD SPACING IS PART OF THIS PARSER'S CONTRACT. The generator's --check and
// the site gates must agree on the same 53 keys; if the object is re-indented the
// parser returns zero languages and both refusals fire (see assertRegistry).

export interface RegistryLanguage {
  name: string
  grammar: string
}

export interface Registry {
  languages: RegistryLanguage[]
  /** Names in declaration order, duplicates included (a shadowed key is a defect). */
  declarations: string[]
  /** name -> resolved grammar (last declaration wins, as JS does). */
  grammars: Map<string, string>
}

export function readRegistry(): Registry {
  const src = readRepo("src/ast/engine.ts")
  const start = src.indexOf("const SUPPORTED_LANGUAGES = {")
  if (start < 0) throw new Error("site-truth: `const SUPPORTED_LANGUAGES = {` not found in src/ast/engine.ts — the registry shape moved and this reader must be repaired, not skipped")
  const end = src.indexOf("\n  } as const", start)
  if (end < 0) throw new Error("site-truth: SUPPORTED_LANGUAGES block has no closing `} as const` — refusing to read a partial registry")
  const grammars = new Map<string, string>()
  const declarations: string[] = []
  for (const line of src.slice(start, end).split("\n")) {
    const m = line.match(/^\s*(?:"([^"]+)"|([a-z0-9_-]+)):\s*"([^"]+)",\s*$/)
    if (!m) continue
    const name = (m[1] ?? m[2])!
    declarations.push(name)
    grammars.set(name, m[3]!)
  }
  const languages = [...grammars].map(([name, grammar]) => ({ name, grammar }))
  return { languages, declarations, grammars }
}

/** The dedicated grammar count: every registry key whose grammar is not `__generic__`. */
export function dedicatedLanguageCount(registry: Registry): number {
  return registry.languages.filter((l) => l.grammar !== "__generic__").length
}

/**
 * The AUTHORITATIVE language→analyzer mapping, read structurally from the
 * `getAnalyzer()` switch in src/ast/engine.ts rather than re-typed as an alias
 * table. This is the same switch that runs in production, so the site's
 * "one family per analyzer module" claim is the engine's own routing:
 *
 *   case "typescript": case "tsx":  -> real-typescript-analyzer
 *   case "css": case "sass":        -> real-css-analyzer      (sass uses the CSS grammar)
 *   case "scss":                    -> real-scss-analyzer
 *   case "hcl": case "terraform":   -> real-hcl-analyzer
 *   case "make":                    -> real-makefile-analyzer
 *
 * It exists because a hand-written alias map had already gone wrong once: the
 * dataset claimed `sass` as an SCSS-family id while `getAnalyzer("sass")`
 * returns RealCssAnalyzer, so the page credited a vocabulary to a module that
 * never runs on .sass files.
 */
export function readAnalyzerModuleMap(): Map<string, string> {
  const src = readRepo("src/ast/engine.ts")
  const start = src.indexOf("async function getAnalyzer(")
  if (start < 0) throw new Error("site-truth: `async function getAnalyzer(` not found in src/ast/engine.ts — the language→module routing moved")
  const end = src.indexOf("default:", start)
  if (end < 0) throw new Error("site-truth: getAnalyzer() has no `default:` branch — refusing to read a partial switch")
  const body = src.slice(start, end)
  const map = new Map<string, string>()
  let pending: string[] = []
  for (const line of body.split("\n")) {
    const c = line.match(/^\s*case "([^"]+)":\s*$/)
    if (c) {
      pending.push(c[1]!)
      continue
    }
    const r = line.match(/real-([a-z0-9-]+)-analyzer/)
    if (r) {
      if (pending.length === 0) throw new Error(`site-truth: getAnalyzer() maps real-${r[1]}-analyzer with no preceding case label — the switch shape moved`)
      for (const id of pending) map.set(id, r[1]!)
      pending = []
    }
  }
  if (pending.length > 0) throw new Error(`site-truth: getAnalyzer() case labels with no analyzer return: ${pending.join(",")}`)
  return map
}

/** The analyzer modules that exist on disk, as bare tokens (`typescript`, `makefile`, …). */
export function listAnalyzerModules(): string[] {
  return readdirSync(path.join(ROOT, "src/ast"))
    .filter((f) => /^real-.*-analyzer\.ts$/.test(f))
    .map((f) => f.replace(/^real-/, "").replace(/-analyzer\.ts$/, ""))
    .sort((a, b) => a.localeCompare(b))
}

// ── 2. Extensions: src/ast/language-detection.ts ─────────────────────────────

export interface ExtensionRoute {
  ext: string
  language: string
  /** True when the route is decided by content sniffing, not by the extension table alone. */
  sniffed: boolean
}

/**
 * Every extension that routes to a language, from EXTENSION_LANGUAGE PLUS the
 * content-sniffing branches that claim an extension the table maps elsewhere:
 *
 *   `.m`  -> matlab      when the head has `function ` / `classdef `
 *   `.h`  -> objective-c when it declares `@interface`/`@protocol`/`@implementation`
 *   `.h`  -> cpp         when C++ markers are present; otherwise the table's `c`
 *
 * The sniffed routes are real routing: a MATLAB `.m` file IS indexed as matlab.
 * Omitting them would understate the family's reach, and the direction this file
 * refuses to understate is the dangerous one. `.h` therefore legitimately appears
 * under three families, exactly as the router decides it — content, not a
 * filename, is what selects the analyzer there.
 *
 * The sniff reader is deliberately narrow: it collects the `return "lang"`
 * targets inside each `if (ext === "x" && content…)` branch of
 * `detectLanguageFromPath` and stops at the next branch or the function's
 * fallthrough. A sniff the reader cannot see understates ext; the gate compares
 * the dataset against THIS reader, so the visible failure would be a stale
 * dataset, not a silent claim.
 */
export function readExtensionRoutes(): ExtensionRoute[] {
  const src = readRepo("src/ast/language-detection.ts")
  const start = src.indexOf("export const EXTENSION_LANGUAGE")
  if (start < 0) throw new Error("site-truth: EXTENSION_LANGUAGE not found in src/ast/language-detection.ts")
  const tableEnd = src.indexOf("const BASENAME_LANGUAGE", start)
  const fnEnd = src.indexOf("return byExtension ?? null", start)
  if (tableEnd < 0 || fnEnd < 0) throw new Error("site-truth: language-detection.ts shape moved (table or fallthrough not found)")

  const routes: ExtensionRoute[] = []
  const seen = new Set<string>()
  const push = (ext: string, language: string, sniffed: boolean): void => {
    const key = `${ext}\u0000${language}`
    if (seen.has(key)) return
    seen.add(key)
    routes.push({ ext, language, sniffed })
  }

  for (const line of src.slice(start, tableEnd).split("\n")) {
    const t = line.trim()
    // Comments are not entries: the table's prose names old spellings (`less`,
    // `jsonc`, …) and a scan that read prose would publish a route that does not
    // exist. Only `"ext": "lang"` / `ext: "lang"` pairs on a non-comment line.
    if (t.startsWith("//") || t.startsWith("*") || t.startsWith("/*") || t.startsWith("export")) continue
    for (const m of t.matchAll(/(?:"([^"]+)"|([A-Za-z0-9_+.-]+))\s*:\s*"([a-z0-9-]+)"/g)) {
      push((m[1] ?? m[2])!, m[3]!, false)
    }
  }

  // Content-sniffing branches, in source order.
  const sniffBody = src.slice(start, fnEnd)
  const branchStarts = [...sniffBody.matchAll(/if \(ext === "([a-z]+)" && content/g)].map((m) => ({ ext: m[1]!, index: m.index! }))
  if (branchStarts.length === 0) throw new Error("site-truth: no `if (ext === \"…\" && content` sniff branches found — language-detection.ts shape moved")
  for (let i = 0; i < branchStarts.length; i++) {
    const from = branchStarts[i]!.index
    const to = i + 1 < branchStarts.length ? branchStarts[i + 1]!.index : fnEnd - start
    for (const m of sniffBody.slice(from, to).matchAll(/return "([a-z0-9-]+)"/g)) push(branchStarts[i]!.ext, m[1]!, true)
  }

  return routes
}

/** ext tokens routed to a specific registry language id, in routing-table order. */
export function extensionsForLanguage(routes: ExtensionRoute[], language: string): string[] {
  return routes.filter((r) => r.language === language).map((r) => r.ext)
}

// ── 3. The emitted relationship vocabulary: src/ast/types.ts ─────────────────
//
// THE ENUM MOVED. Until the 2026-10-17 consolidation there were three
// RelationshipType enums and `src/ast/engine.ts` carried the one analyzers read.
// A verifier written against that layout kept parsing engine.ts and, after the
// consolidation, found no enum at all — so its derived vocabulary was empty and
// every family reported `invented=<all types>`. The authoritative definition is
// now `export enum RelationshipType` in src/ast/types.ts (engine.ts re-exports
// it as `ASTEngine.RelationshipType`), and this reader refuses a missing/partial
// enum rather than returning an empty list that would make every check vacuous.
//
// The enum lists deprecated aliases (`Call`, `Inheritance`, `Provides`, …) whose
// VALUES are canonical, so the unique value list is the emitted vocabulary and
// the member map lets analyzer source (`RelationshipType.Call`) resolve to
// `calls`. `graph.ts`'s enum adds DERIVED values no analyzer emits; this reader
// never touches it.

export interface RelationshipVocabulary {
  /** Member name (as written in analyzer source) -> stored value. */
  members: Map<string, string>
  /** Unique values in enum declaration order — the emitted vocabulary. */
  emitted: string[]
}

export function readRelationshipVocabulary(): RelationshipVocabulary {
  const src = readRepo("src/ast/types.ts")
  const at = src.indexOf("export enum RelationshipType")
  if (at < 0) throw new Error("site-truth: `export enum RelationshipType` not found in src/ast/types.ts — the authoritative enum moved; repair this reader rather than assuming a vocabulary")
  const end = src.indexOf("\n}", at)
  if (end < 0) throw new Error("site-truth: RelationshipType enum has no closing brace — refusing to read a partial enum")
  const members = new Map<string, string>()
  for (const line of src.slice(at, end).split("\n")) {
    const t = line.trimStart()
    // Comments are not members. The enum's prose quotes the old spellings
    // (`Imports = "brain_import"`, removed aliases); a regex over the raw slice
    // once reported a fabricated member from a comment.
    if (t.startsWith("//") || t.startsWith("*") || t.startsWith("/*")) continue
    const m = t.match(/^([A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"([^"]+)"/)
    if (m) members.set(m[1]!, m[2]!)
  }
  const emitted = [...new Set(members.values())]
  return { members, emitted }
}

/**
 * What one analyzer module can CONSTRUCT, by the same broad source scan the L1
 * gate has always used (now reading the authoritative enum). See the header note:
 * this over-reports on purpose.
 */
export function deriveEmittedTypes(moduleToken: string, vocabulary: RelationshipVocabulary, moduleSet: Set<string>, seen: Set<string> = new Set()): Set<string> {
  const found = new Set<string>()
  if (!moduleSet.has(moduleToken) || seen.has(moduleToken)) return found
  seen.add(moduleToken)
  const src = readRepo(`src/ast/real-${moduleToken}-analyzer.ts`)

  for (const m of src.matchAll(/RelationshipType\.([A-Za-z]+)/g)) {
    const v = vocabulary.members.get(m[1]!)
    if (v) found.add(v)
  }
  // The string-literal spelling, filtered to the vocabulary: analyzer source also
  // writes `type: "boolean"`, `label: "web_framework"` and pattern kinds, and an
  // unfiltered scan files those as relationship types. The value is not always
  // adjacent to the colon (Java picks `extends`/`implements` by ternary), so the
  // whole remainder of the line is considered — a lazy adjacency pattern
  // under-reported Java's extends edge.
  for (const m of src.matchAll(/(?:type|relationshipType|label):([^\n]*)/g)) {
    for (const q of m[1]!.matchAll(/"([a-z_]+)"/g)) if (vocabulary.emitted.includes(q[1]!)) found.add(q[1]!)
  }
  // The positional helper spelling: this.rel(scope, "contains", name, node, 1.0).
  // Missing it made Julia publish an empty vocabulary.
  for (const m of src.matchAll(/\brel\(\s*[^,()]+,\s*"([a-z_]+)"/g)) if (vocabulary.emitted.includes(m[1]!)) found.add(m[1]!)

  // Delegation. HTML resolves inline <script>/<style> blocks through the real
  // JavaScript/TypeScript/CSS analyzers and merges their relationships; a language
  // host's effective vocabulary includes its delegate's, because those edges are
  // real and stored under the host language.
  for (const m of src.matchAll(/require\(\s*["']\.\/real-([a-z0-9-]+)-analyzer["']\s*\)|Real([A-Za-z0-9]+)Analyzer/g)) {
    const candidate = (m[1] ?? m[2]?.toLowerCase()) ?? ""
    if (!candidate) continue
    for (const t of deriveEmittedTypes(candidate, vocabulary, moduleSet, seen)) found.add(t)
  }
  return found
}

// ── 4. Fail-closed assertions shared by the generator and the gate ────────────

export interface EngineTruth {
  registry: Registry
  analyzerModuleMap: Map<string, string>
  modules: string[]
  extensionRoutes: ExtensionRoute[]
  vocabulary: RelationshipVocabulary
  /** module token -> registry language ids routed to it, registry declaration order. */
  languagesByModule: Map<string, string[]>
  /** module token -> what its source can construct. */
  emitsByModule: Map<string, Set<string>>
}

/**
 * Read every source above and refuse a tree that cannot support the published
 * claims. This is the fail-closed core: a zero/partial read must never become a
 * smaller dataset that still renders.
 */
export function readEngineTruth(): EngineTruth {
  const registry = readRegistry()
  if (registry.languages.length === 0) throw new Error("site-truth: SUPPORTED_LANGUAGES parsed to zero languages")
  const shadowed = registry.declarations.filter((k, i) => registry.declarations.indexOf(k) !== i)
  if (shadowed.length > 0) throw new Error(`site-truth: registry declares duplicate languages: ${[...new Set(shadowed)].join(",")}`)
  const dedicated = dedicatedLanguageCount(registry)
  if (dedicated !== registry.languages.length) {
    const generic = registry.languages.filter((l) => l.grammar === "__generic__").map((l) => l.name)
    throw new Error(`site-truth: registry keeps generic-grammar languages (${generic.join(",")}); the site publishes "every registry language resolves to a real grammar" and cannot while this is true`)
  }

  const analyzerModuleMap = readAnalyzerModuleMap()
  const modules = listAnalyzerModules()
  const moduleSet = new Set(modules)
  const unroute = registry.languages.map((l) => l.name).filter((n) => !analyzerModuleMap.has(n))
  if (unroute.length > 0) throw new Error(`site-truth: registry languages with no getAnalyzer() route: ${unroute.join(",")}`)
  const phantoms = [...analyzerModuleMap.values()].filter((m) => !moduleSet.has(m))
  if (phantoms.length > 0) throw new Error(`site-truth: getAnalyzer() routes to analyzer modules that do not exist: ${[...new Set(phantoms)].join(",")}`)
  const unroutedModules = modules.filter((m) => ![...analyzerModuleMap.values()].includes(m))
  if (unroutedModules.length > 0) throw new Error(`site-truth: analyzer modules no registry language routes to: ${unroutedModules.join(",")} — publishing one family per analyzer module requires a bijection`)

  const extensionRoutes = readExtensionRoutes()
  if (extensionRoutes.length === 0) throw new Error("site-truth: extension router parsed to zero routes")
  const extensionPhantoms = extensionRoutes.map((r) => r.language).filter((l) => !registry.grammars.has(l))
  if (extensionPhantoms.length > 0) throw new Error(`site-truth: extensions route to languages outside the registry: ${[...new Set(extensionPhantoms)].join(",")}`)

  const vocabulary = readRelationshipVocabulary()
  if (vocabulary.emitted.length === 0) throw new Error("site-truth: emitted relationship vocabulary is empty")

  const languagesByModule = new Map<string, string[]>()
  for (const lang of registry.languages) {
    const mod = analyzerModuleMap.get(lang.name)!
    if (!languagesByModule.has(mod)) languagesByModule.set(mod, [])
    languagesByModule.get(mod)!.push(lang.name)
  }
  const emitsByModule = new Map<string, Set<string>>()
  for (const mod of modules) emitsByModule.set(mod, deriveEmittedTypes(mod, vocabulary, moduleSet))

  return { registry, analyzerModuleMap, modules, extensionRoutes, vocabulary, languagesByModule, emitsByModule }
}

/**
 * `ext` display string for one family: every extension the router sends to one of
 * the family's language ids, dotted, in routing-table order. A routed extension
 * whose token is a filename rather than an extension keeps its conventional
 * spelling (`makefile` -> `Makefile`).
 *
 * The field is "extensions", not "file names": basename routing (Makefile,
 * Rakefile, .bashrc, …) lives in BASENAME_LANGUAGE and is a different claim; it
 * is not folded in here because the site renders this string as the extension
 * list and a basename is not an extension.
 */
export function extensionLabelFor(truth: EngineTruth, moduleToken: string): string {
  const ids = truth.languagesByModule.get(moduleToken) ?? []
  const exts = truth.extensionRoutes.filter((r) => ids.includes(r.language)).map((r) => r.ext)
  const unique = [...new Set(exts)]
  if (unique.length === 0) throw new Error(`site-truth: no routed extension for analyzer module ${moduleToken} (ids=${ids.join(",")}) — the site cannot show the family without stating what it reads`)
  const NAME_TOKENS: Record<string, string> = { makefile: "Makefile" }
  return unique.map((e) => `.${NAME_TOKENS[e] ?? e}`).join(", ")
}

/** Files that must exist for the derivation to be meaningful; used by both consumers. */
export function assertTruthSources(): void {
  for (const rel of ["src/ast/engine.ts", "src/ast/types.ts", "src/ast/language-detection.ts"]) {
    if (!existsSync(path.join(ROOT, rel))) throw new Error(`site-truth: source artifact missing: ${rel}`)
  }
}
